    typedef enum logic [1:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING
    } state_t;

    state_t current_state, next_state;

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
        end else begin
            current_state <= next_state;
        end
    end

    // Output and next state logic
    always_comb begin
        next_state = current_state;
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;

        case (current_state)
            WALK_LEFT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else begin
                    walk_left = 1'b1;
                end
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    aaah = 1'b1;
                end else begin
                    walk_right = 1'b1;
                end
            end

            FALLING: begin
                if (ground) begin
                    // Resume walking in the previous direction
                    if (current_state == WALK_LEFT) begin
                        walk_left = 1'b1;
                    end else begin
                        walk_right = 1'b1;
                    end
                end else begin
                    // Still falling, no change in direction
                    aaah = 1'b1;
                end
            end
        endcase
    end

    // State transition logic for direction change on bump
    always_comb begin
        if (current_state == WALK_LEFT) begin
            if (bump_right || bump_left) begin
